begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions,pg_temp;
select no_plan();
set local role authenticated;
select set_config('request.jwt.claim.sub','20000000-0000-0000-0000-000000000001',true);
select public.manage_icu_device('30000000-0000-0000-0000-000000000002','add','{"bed":"TEST-FLAG","device_type":"vent","vent_mode":"apvcmv","notes":"Keep note"}','{}');
select public.record_icu_rounding_action(id,'critical','{"flolan":true,"proned":false,"other":""}',updated_at) from public.icu_patients where bed='TEST-FLAG';
select lives_ok($$select public.record_icu_rounding_action(id,'flag','{"active":true,"note":"Difficult Airway"}',updated_at) from public.icu_patients where bed='TEST-FLAG'$$,'Room flag saved');
select ok((select rounding_data#>>'{flag,note}'='Difficult Airway' and rounding_data#>>'{flag,active}'='true' and is_critical_vent and is_flolan and notes='Keep note' from public.icu_patients where bed='TEST-FLAG'),'Flag preserves Critical Vent and rounding note');
select throws_ok($$select public.record_icu_rounding_action(id,'flag','{"active":true}',updated_at-interval '1 second') from public.icu_patients where bed='TEST-FLAG'$$,'40001','This patient was updated. Refresh the card and try again.','Stale flag edits rejected');
select throws_ok($$select public.record_icu_rounding_action(id,'flag',jsonb_build_object('active',true,'note',repeat('x',201)),updated_at) from public.icu_patients where bed='TEST-FLAG'$$,'22023','Keep the flag note under 200 characters','Flag note limit enforced');
select throws_ok($$select public.record_icu_rounding_action(id,'flag','{"active":"true"}',updated_at) from public.icu_patients where bed='TEST-FLAG'$$,'22023','Select a flag status','Invalid flag status rejected');
select lives_ok($$select public.extubate_icu_patient(id,'hfnc','{"flow":40,"fio2":40}',now(),updated_at) from public.icu_patients where bed='TEST-FLAG'$$,'Extubation retains flag');
select ok((select rounding_data#>>'{flag,active}'='true' and not is_critical_vent from public.icu_patients where bed='TEST-FLAG'),'Flag remains active on non-vent patient independently');
select lives_ok($$select public.record_icu_rounding_action(id,'flag','{"active":false,"note":"ignored"}',updated_at) from public.icu_patients where bed='TEST-FLAG'$$,'Room flag removed');
select ok((select rounding_data#>>'{flag,active}'='false' and rounding_data#>>'{flag,note}' is null and notes='Keep note' from public.icu_patients where bed='TEST-FLAG'),'Remove clears only flag note');
select is((select count(*)::int from public.icu_patient_events e join public.icu_patients p on p.id=e.icu_patient_id where p.bed='TEST-FLAG' and e.event_data->>'action'='flag_recorded'),2,'Flag changes recorded in history');
select set_config('test.flagid',id::text,true) from public.icu_patients where bed='TEST-FLAG';
select set_config('request.jwt.claim.sub','20000000-0000-0000-0000-000000000003',true);
select throws_ok($$select public.record_icu_rounding_action(current_setting('test.flagid')::uuid,'flag','{"active":true}',now())$$,'42501','Patient unavailable or not authorized','Unauthorized flag changes rejected');
select * from finish();
rollback;
